function Services({ items }: { items: any[] }) {
  const t = useT();
  const { L } = usePrefs();
  const reduced = useReduced();
  const n = items.length;
  // An endless strip: pos counts up/down forever, the card at strip place k is items[k mod n], so the order is
  // always ... 1 2 3 1 2 3 ... in both directions (with few cards the same card shows more than once).
  // Each place keeps its React key while pos moves, so every card simply slides one place.
  const [pos, setPos] = useState(0);
  const c = n ? mod(pos, n) : 0;
  // One change at a time: a click, swipe or autoplay tick that comes while the cards are still moving is ignored.
  // (Before, autoplay kept its own clock, so a click right before a tick made two slides run back to back and the cards looked stuck.)
  const lock = useRef(0);
  const free = () => { const now = Date.now(); if (now < lock.current) return false; lock.current = now + 750; return true; };

  // autoplay (paused on hover, off for reduced motion). The timer starts again after every slide, even one made by hand.
  const paused = useRef(false);
  const hold = useRef(0); // autoplay waits until this time (after a footer link picked a card)
  const entering = useRef(false); // true while the scroll intro below is still bringing the cards in: no autoplay yet
  useEffect(() => {
    if (reduced || n < 2) return;
    const id = window.setInterval(() => { if (!paused.current && !entering.current && !document.hidden && Date.now() > hold.current && free()) setPos((x) => x + 1); }, 3800);
    return () => clearInterval(id);
  }, [reduced, n, pos]);

  const step = useCallback((fwd: boolean) => { if (free()) setPos((x) => x + (fwd ? 1 : -1)); }, []);
  const pick = (i: number) => { if (free()) setPos((x) => x + shortest(mod(x, n), i, n)); }; // a dot: the shortest way to that card
  const goTo = (k: number) => { if (free()) setPos(k); };                                  // a card on the strip: exactly to it

  // swipe / drag (touch and mouse); Arabic flips the direction
  const stage = useRef<HTMLDivElement>(null);
  const justDragged = useRef(false);
  useEffect(() => {
    const el = stage.current;
    if (!el || n < 2) return;
    let st: { x: number; y: number; done: boolean; h: boolean | null } | null = null;
    let tm = 0;
    const go = (dx: number) => {
      const fwd = dx < 0;
      justDragged.current = true;
      clearTimeout(tm);
      tm = window.setTimeout(() => { justDragged.current = false; }, 300);
      step(fwd);
    };
    const down = (x: number, y: number) => { st = { x, y, done: false, h: null }; };
    const move = (x: number, y: number, ev: Event | null) => {
      if (!st) return;
      const dx = x - st.x, dy = y - st.y;
      if (st.h === null && (Math.abs(dx) > 8 || Math.abs(dy) > 8)) st.h = Math.abs(dx) > Math.abs(dy);
      if (st.h && ev && ev.cancelable) ev.preventDefault();
      if (st.h && !st.done && Math.abs(dx) > 45) { st.done = true; go(dx); }
    };
    const up = () => { st = null; };
    const ts = (e: TouchEvent) => { const p = e.touches[0]; down(p.clientX, p.clientY); };
    const tmv = (e: TouchEvent) => { const p = e.touches[0]; move(p.clientX, p.clientY, e); };
    const pd = (e: PointerEvent) => { if (e.pointerType !== 'touch') down(e.clientX, e.clientY); };
    const pm = (e: PointerEvent) => { if (e.pointerType !== 'touch') move(e.clientX, e.clientY, null); };
    const pu = (e: PointerEvent) => { if (e.pointerType !== 'touch') up(); };
    el.addEventListener('touchstart', ts, { passive: true });
    el.addEventListener('touchmove', tmv, { passive: false });
    el.addEventListener('touchend', up);
    el.addEventListener('touchcancel', up);
    el.addEventListener('pointerdown', pd);
    window.addEventListener('pointermove', pm);
    window.addEventListener('pointerup', pu);
    return () => {
      clearTimeout(tm);
      el.removeEventListener('touchstart', ts);
      el.removeEventListener('touchmove', tmv);
      el.removeEventListener('touchend', up);
      el.removeEventListener('touchcancel', up);
      el.removeEventListener('pointerdown', pd);
      window.removeEventListener('pointermove', pm);
      window.removeEventListener('pointerup', pu);
    };
  }, [n, step]);

  // sideways scroll (trackpad / shift+wheel)
  const wheelT = useRef(0);
  const onWheel = (e: React.WheelEvent) => {
    const dx = e.deltaX || (e.shiftKey ? e.deltaY : 0);
    if (Math.abs(dx) < 18 || Math.abs(dx) < Math.abs(e.deltaY) * (e.shiftKey ? 0 : 1)) return;
    const now = Date.now();
    if (now - wheelT.current < 650) return;
    wheelT.current = now;
    step(dx > 0);
  };

  const active = items[c];

  // Scroll intro (computers and phones, motion allowed), like IMPACT BBDO: the section holds still under the nav for a short
  // stretch of scrolling (about 75% of a screen). Meanwhile the heading block (label, title, squiggle, line) starts big
  // on the right and glides in one smooth curve up to its place at the top left, getting smaller on the way (mirrored
  // in Arabic); then the sticker + "All services" come in and the cards come toward you from far away. It follows the scroll both ways, so scrolling back up plays it backwards and coming down again replays it.
  const phone = useMatch('(max-width: 760px)');
  const pin = !reduced;
  const track = useRef<HTMLDivElement>(null);
  const stick = useRef<HTMLDivElement>(null);
  const fit = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const tr = track.current, st = stick.current, ft = fit.current;
    if (!pin || !tr || !st || !ft) return;
    const col = ft.querySelector<HTMLElement>('.mm-headrow > .mm-col');
    const right = ft.querySelector<HTMLElement>('.mm-svc-headright');
    const clip = ft.querySelector<HTMLElement>('.mm-svc-clip');
    const ctrl = ft.querySelector<HTMLElement>('.mm-svc-ctrl');
    if (!col) return;
    const moving = [col, right, clip, ctrl].filter(Boolean) as HTMLElement[];
    moving.forEach((e) => { e.style.transition = 'none'; e.style.willChange = 'transform, opacity'; });
    col.style.transformOrigin = 'center center';
    const clamp = (v: number) => Math.min(1, Math.max(0, v));
    const ease = (v: number) => v * v * (3 - 2 * v);
    let navH = 0, stickH = 0, scale = 1, raf = 0, cur = -1;
    let off = { x: 0, y: 0, w: 1, h: 1 }; // where the heading block sits normally, inside the pinned box
    const layout = () => {
      navH = document.querySelector('.mm-ihead')?.getBoundingClientRect().height || 0;
      stickH = window.innerHeight - navH;
      st.style.top = navH + 'px';
      st.style.height = stickH + 'px';
      ft.style.transform = 'none';
      scale = Math.min(1, stickH / ft.offsetHeight); // a little smaller on short screens so it all fits
      ft.style.transform = scale < 1 ? `scale(${scale})` : 'none';
      tr.style.height = stickH + window.innerHeight * 0.75 + 'px'; // how long it holds: 75% of a screen of scrolling
      const keep = col.style.transform;
      col.style.transform = 'none';
      const r = col.getBoundingClientRect(), sr = st.getBoundingClientRect();
      off = { x: r.left + r.width / 2 - sr.left, y: r.top + r.height / 2 - sr.top, w: r.width, h: r.height };
      col.style.transform = keep;
    };
    const target = () => {
      const tb = tr.getBoundingClientRect();
      return clamp((navH - tb.top) / Math.max(1, tb.height - stickH));
    };
    const paint = (p: number) => {
      // one smooth glide from big on the right (middle height) to its place: sideways a little ahead of upwards,
      // so it travels on a soft curve instead of a straight line
      const t = clamp(p / 0.62);
      const gx = 1 - Math.pow(1 - t, 2.2);      // sideways: quick start, gentle end
      const gy = t * t * (3 - 2 * t);           // upwards: smooth in and out
      const c = ease(clamp((p - 0.52) / 0.45)); // then the sticker + "All services" + cards
      const sr = st.getBoundingClientRect();
      const rtl = getComputedStyle(st).direction === 'rtl';
      let big: number, x0: number; // start size, and where the block's centre starts (px)
      if (phone) {
        // phones: the heading already fills the width, so it starts a bit bigger and pushed to the right, partly off screen
        big = Math.min(1.35, (sr.height * 0.5) / off.h);
        x0 = off.x + (rtl ? -1 : 1) * sr.width * 0.3;
      } else {
        big = Math.max(1, Math.min(1.6, (sr.width * 0.6) / off.w, (sr.height * 0.6) / off.h));
        const half = (off.w * big) / 2, m = sr.width * 0.05;
        x0 = rtl ? m + half : sr.width - m - half;
      }
      const dx = ((x0 - off.x) / scale) * (1 - gx), dy = ((sr.height / 2 - off.y) / scale) * (1 - gy);
      col.style.transform = `translate(${dx}px, ${dy}px) scale(${1 + (big - 1) * (1 - gy)})`;
      if (right) { right.style.opacity = String(c); right.style.transform = `translateY(${(1 - c) * 30}px)`; }
      // the cards come toward you from far away (small and faint -> full size) as you scroll
      if (clip) { clip.style.opacity = String(Math.min(1, c * 1.6)); clip.style.transform = `perspective(1200px) translateZ(${(-(1 - c) * 900).toFixed(1)}px)`; }
      if (ctrl) ctrl.style.opacity = String(c);
      entering.current = c < 1;
    };
    const tick = () => {
      raf = 0;
      const t = target();
      cur = cur < 0 ? t : cur + (t - cur) * 0.18; // a little smoothing, like IMPACT's scrub
      if (Math.abs(t - cur) < 0.001) cur = t;
      paint(cur);
      if (cur !== t) raf = requestAnimationFrame(tick);
    };
    const kick = () => { if (!raf) raf = requestAnimationFrame(tick); };
    // phones: the address bar coming and going changes only the height; re-measuring then would make the page jump
    let lastW = window.innerWidth;
    const onResize = () => {
      if (!(phone && window.innerWidth === lastW)) layout();
      lastW = window.innerWidth;
      cur = target(); paint(cur);
    };
    layout(); cur = target(); paint(cur);
    window.addEventListener('scroll', kick, { passive: true });
    window.addEventListener('resize', onResize);
    return () => {
      window.removeEventListener('scroll', kick);
      window.removeEventListener('resize', onResize);
      cancelAnimationFrame(raf);
      entering.current = false;
      // undo only what the intro set (the elements keep their own inline styles)
      moving.forEach((e) => { e.style.transform = ''; e.style.opacity = ''; e.style.transition = ''; e.style.willChange = ''; });
      col.style.transformOrigin = '';
      tr.style.height = ''; st.style.top = ''; st.style.height = ''; ft.style.transform = '';
    };
  }, [pin, n, phone]);

  // A link /#services or /#service-N (footer, menu): scroll to where the cards are fully in (past the pinned intro), then bring card N to the
  // middle. Runs again on every click (loc.key), also when the visitor is already on the home page.
  const loc = useLocation();
  useEffect(() => {
    const m = /^#service(?:s|-(\d+))$/.exec(loc.hash); // #services = just the section, #service-N = that card too
    if (!m || !n) return;
    const want = m[1] ? Math.min(n, Math.max(1, Number(m[1]))) - 1 : -1;
    let tries = 0, tm = 0;
    const go = () => {
      const tr = track.current, sec = document.getElementById('services');
      if (!sec || (pin && !tr?.style.height)) { if (tries++ < 30) tm = window.setTimeout(go, 100); return; } // not laid out yet
      const navH = document.querySelector('.mm-ihead')?.getBoundingClientRect().height || 0;
      const top = pin && tr
        ? window.scrollY + tr.getBoundingClientRect().top + tr.offsetHeight - (window.innerHeight - navH) - navH // end of the intro
        : window.scrollY + sec.getBoundingClientRect().top - navH;
      window.scrollTo({ top: Math.max(0, top), behavior: reduced ? 'auto' : 'smooth' });
      if (want < 0) return;
      lock.current = 0; // a footer pick always goes through
      hold.current = Date.now() + 9000; // and stays in front for a while before autoplay moves on
      setPos((x) => x + shortest(mod(x, n), want, n));
    };
    tm = window.setTimeout(go, 150);
    return () => clearTimeout(tm);
  }, [loc.key, n]); // eslint-disable-line react-hooks/exhaustive-deps

  return (
    <section id="services" data-bg="bg2" className={'mm-svcs' + (pin ? ' mm-svc-pinned' : '')}>
      <div ref={track} className="mm-svc-track"><div ref={stick} className="mm-svc-stick"><div ref={fit} className="mm-svc-fit">
      {/* soft brand shapes floating behind the section */}
      <span className="mm-svc-blob b1" aria-hidden="true" />
      <span className="mm-svc-blob b2" aria-hidden="true" />
      <span className="mm-svc-blob b3" aria-hidden="true" />
      <div className="mm-wrap mm-svc-head">
        <div className="mm-headrow">
          <div className="mm-col" style={{ gap: 16 }}>
            <span className="rv rv-left mm-eyebrow">{t.whatWeDo}</span>
            <h2 className="mm-h2" style={{ fontSize: 104 }}><span className="ln"><span>{t.ourServices}</span></span></h2>
            {/* an orange squiggle that draws itself under the title */}
            <svg className="rv mm-squiggle" viewBox="0 0 320 26" aria-hidden="true"><path d="M4 16 C 24 2, 44 2, 64 14 S 104 26, 124 14 S 164 2, 184 14 S 224 26, 244 14 S 284 2, 316 12" /></svg>
            <p className="rv rv-left mm-svc-sub">{t.svcSub}</p>
          </div>
          <div className="mm-svc-headright">
            <SvcBadge />
            <a className="rv rv-right mm-more" href="#services">{t.allServices}</a>
          </div>
        </div>
      </div>

      {n > 0 && (
        <>
          <div className="mm-svc-clip rv rv-pop" style={{ transitionDelay: '.15s' }}>
            <div ref={stage} className="mm-svc-3d" onMouseEnter={() => { paused.current = true; }} onMouseLeave={() => { paused.current = false; }} onWheel={onWheel}>
              <div className="mm-svc-deck">
                {Array.from({ length: n > 1 ? SLOTS * 2 + 1 : 1 }, (_, j) => {
                  const k = n > 1 ? pos - SLOTS + j : pos; // place on the endless strip
                  const i = mod(k, n);
                  const it = items[i];
                  const o = k - pos;
                  const a = Math.abs(o);
                  const on = o === 0;
                  const hidden = a > 2;
                  return (
                    <button
                      key={k}
                      type="button"
                      className="mm-svc"
                      onClick={() => { if (!justDragged.current) goTo(k); }}
                      aria-label={L(it.title)}
                      aria-hidden={hidden || undefined}
                      tabIndex={hidden ? -1 : 0}
                      style={{
                        border: `1px solid ${on ? '#F68B1F' : '#22395A'}`,
                        background: it.bg || '#0B4A94',
                        color: it.fg || '#ffffff',
                        transform: `translateX(${o * 230}px) translateZ(${-a * 160}px) rotateY(${o * -26}deg) scale(${Math.max(0.7, 1 - a * 0.12)})`,
                        opacity: hidden ? 0 : Math.max(0.25, 1 - a * 0.3),
                        zIndex: 50 - a * 10,
                        filter: on ? 'none' : 'brightness(0.55)',
                        boxShadow: on ? '0 30px 60px -10px rgba(0,0,0,0.7), 0 0 0 2px #F68B1F' : '0 12px 30px rgba(0,0,0,0.5)',
                        pointerEvents: hidden ? 'none' : 'auto',
                      }}
                    >
                      <span className="mm-svc-num">{pad2(i + 1)}</span>
                      <span className="mm-svc-ico" aria-hidden="true">{SVC_ICONS[i % SVC_ICONS.length]}</span>
                      <span className="mm-col" style={{ gap: 12, position: 'relative' }}>
                        <span className="mm-svc-title">{L(it.title)}</span>
                        <span className="mm-svc-short">{L(it.short)}</span>
                      </span>
                    </button>
                  );
                })}
              </div>
            </div>
          </div>

          <div className="mm-wrap mm-svc-ctrl">
            <div className="mm-tags" aria-live="polite">
              {(active?.tags || []).map((tg: L, k: number) => L(tg) && <span key={`${c}-${k}`} className="mm-tag" style={{ animationDelay: `${k * 0.06}s` }}>{L(tg)}</span>)}
            </div>
            {n > 1 && (
              <div className="mm-svc-nav">
                <button type="button" className="mm-circle" onClick={() => step(false)} aria-label={t.aPrevS}><IconArrow dir="left" /></button>
                <div className="mm-dots">
                  {items.map((it, i) => (
                    <button key={it.id ?? i} type="button" className="mm-sdot" onClick={() => pick(i)} aria-label={L(it.title)} aria-current={i === c || undefined}
                      style={{ width: i === c ? 32 : 10, background: i === c ? '#F68B1F' : '#2A4366' }} />
                  ))}
                </div>
                <button type="button" className="mm-circle" onClick={() => step(true)} aria-label={t.aNextS}><IconArrow dir="right" /></button>
              </div>
            )}
          </div>
        </>
      )}
      {n === 0 && <div className="mm-svc-ctrl" />}
      </div></div></div>
    </section>
  );
}

// =====================================================================
// WORK — featured card + bento wall
// =====================================================================
const BENTO = [
  { cls: 'mm-g1', anim: 'rv-left', delay: 0, bg: '#0B4A94', ph: '#C5D6EC', fg: '#ffffff', meta: '#C5D6EC', tsz: 40, msz: 15 },
  { cls: 'mm-g2', anim: 'rv-right', delay: 0.12, bg: '#F68B1F', ph: '#3A2410', fg: '#0E1B33', meta: '#0E1B33', tsz: 28, msz: 14 },
  { cls: 'mm-g3', anim: 'rv-right', delay: 0, bg: '#1B2A40', ph: '#9FB8D9', fg: '#ffffff', meta: '#C5D6EC', tsz: 32, msz: 14 },
  { cls: 'mm-g4', anim: 'rv-pop', delay: 0, bg: '#0E5E95', ph: '#D5E3F5', fg: '#ffffff', meta: '#E6EFFA', tsz: 28, msz: 14 },
  { cls: 'mm-g5', anim: 'rv-pop', delay: 0.15, bg: '#2A1A0C', ph: '#E9C9A6', fg: '#ffffff', meta: '#E9C9A6', tsz: 28, msz: 14 },
];

// live = real projects from the dashboard (not the loading placeholders): then each card opens Work with that client first
function Work({ items, live }: { items: any[]; live: boolean }) {
  const t = useT();
  const { L } = usePrefs();
  if (!items.length) return null;
  const [feat, ...rest] = items;
  const bento = rest.slice(0, 5);
  return (
    <section id="projects" className="mm-work">
      <div className="mm-wrap mm-sec mm-col" style={{ gap: 48 }}>
        <div className="mm-headrow">
          <div className="mm-col" style={{ gap: 16 }}>
            <span className="rv rv-left mm-eyebrow">{t.theWork}</span>
            <h2 className="mm-h2" style={{ fontSize: 104 }}>
              <span className="ln"><span>{t.workWeAre}</span></span>
              <span className="ln"><span style={{ transitionDelay: '.12s' }}>{t.proudOf}</span></span>
            </h2>
          </div>
          <Link className="rv rv-right mm-more" to="/work">{t.viewAll}</Link>
        </div>

        <Link to={live && feat.id ? `/work?client=${feat.id}` : '/work'} className="mm-card rv rv-pop mm-feat">
          <span className="mm-img mm-ph" style={{ background: '#123E73', color: '#9FB8D9' }}>
            {feat.url ? <Media url={feat.url} poster={feat.poster_url} kind={feat.kind} alt={L(feat.client_name)} /> : t.featImg}
          </span>
          <span className="mm-featbar">
            <span className="mm-col" style={{ gap: 10, minWidth: 0 }}>
              <span className="mm-badge">{t.featured}</span>
              <span className="mm-feat-title">{L(feat.client_name)}</span>
            </span>
            <span className="mm-arrow"><IconArrow dir="diag" size={24} /></span>
          </span>
        </Link>

        {bento.length > 0 && (
          <div className={`mm-bento mm-bn${bento.length}`}>
            {bento.map((w, i) => {
              const b = BENTO[i];
              const has = !!w.url;
              return (
                <Link key={w.id ?? i} to={live && w.id ? `/work?client=${w.id}` : '/work'} className={`mm-card mm-bcard ${b.cls} rv ${b.anim}`} style={{ color: has ? '#ffffff' : b.fg, transitionDelay: b.delay ? `${b.delay}s` : undefined }}>
                  <span className="mm-img mm-ph" style={{ background: b.bg, color: b.ph }}>
                    {has ? <Media url={w.url} poster={w.poster_url} kind={w.kind} alt={L(w.client_name)} /> : t.projImg}
                  </span>
                  {has && <span className="mm-shade" />}
                  <span className="mm-view">{t.viewProject}</span>
                  <span className="mm-bcap">
                    <span className="mm-btitle" style={{ fontSize: b.tsz }}>{L(w.client_name)}</span>
                  </span>
                </Link>
              );
            })}
          </div>
        )}
      </div>
    </section>
  );
}

// =====================================================================
// TRUSTED BY — moving band of client logos with the Minto symbol between them
// =====================================================================
function Clients({ items }: { items: any[] }) {
  const t = useT();
  const { theme } = usePrefs();
  const dark = theme === 'dark';
  const sym = useLogo();
  if (!items.length) return null;
  // the band scrolls by half its width, so it is two identical halves, each long enough to fill a wide screen
  const perHalf = Math.max(1, Math.ceil(8 / items.length));
  const half = Array.from({ length: perHalf }, () => items).flat();
  const all = [...half, ...half];
  const logo = (c: any) => {
    if (dark) {
      if (c.logo_dark_url) return { src: c.logo_dark_url, fx: 'none' };
      if (c.logo_light_url) return { src: c.logo_light_url, fx: 'var(--logofx)' };
    } else {
      if (c.logo_light_url) return { src: c.logo_light_url, fx: 'none' };
      if (c.logo_dark_url) return { src: c.logo_dark_url, fx: 'brightness(0)' };
    }
    return null;
  };
  return (
    <section aria-label={t.trustedBy} className="mm-trust">
      <div className="mm-wrap mm-trust-head">
        <span className="rv rv-left mm-eyebrow" style={{ whiteSpace: 'nowrap' }}>{t.trustedBy}</span>
        <span style={{ flex: 1, height: 1, background: 'var(--line)' }} />
      </div>
      <div className="mm-logobar">
        <div className="mm-logos" style={{ animationDuration: `${half.length * 5}s` }}>
          {all.map((c, k) => {
            const lg = logo(c);
            const copy = k >= items.length;
            return (
              <span key={k} className="mm-logoitem" aria-hidden={copy || undefined}>
                <span className="mm-clogo" style={{ filter: lg ? lg.fx : undefined }}>
                  {lg ? <img src={lg.src} alt={copy ? '' : c.name} loading="lazy" decoding="async" /> : <span className="mm-cname">{c.name}</span>}
                </span>
                <img className="mm-sym" src={sym} alt="" width={38} height={40} />
              </span>
            );
          })}
        </div>
      </div>
    </section>
  );
}

// =====================================================================
// TESTIMONIALS — floating 3D deck + video panel
// =====================================================================
// One shared testimonials video (a reel): sits beside the cards on computers, or replaces them on phones (chosen in the dashboard).
// It plays by itself, muted, while it is on screen; the sound button turns the sound on. The Minto badge spins on top of it.
function TReel({ url }: { url: string }) {
  const t = useT();
  const reduced = useReduced();
  const ref = useRef<HTMLVideoElement>(null);
  const [muted, setMuted] = useState(true);
  useEffect(() => {
    const v = ref.current;
    if (!v || reduced || typeof IntersectionObserver === 'undefined') return;
    const io = new IntersectionObserver(([e]) => { if (e.isIntersecting) v.play().catch(() => {}); else v.pause(); }, { threshold: 0.25 });
    io.observe(v);
    return () => io.disconnect();
  }, [url, reduced]);
  const toggle = () => { const v = ref.current; if (!v) return; v.muted = !v.muted; setMuted(v.muted); if (v.paused) v.play().catch(() => {}); };
  return (
    <div className="mm-treel rv rv-pop">
      <div className="mm-treel-frame">
        {url ? <video ref={ref} src={url + '#t=0.1'} muted loop playsInline preload="metadata" aria-label={t.aSay} /> : <span className="mm-treel-ph">{t.testiVideo}</span>}
        {url && <button type="button" className="mm-treel-snd" onClick={toggle} aria-pressed={!muted} aria-label={muted ? t.soundOn : t.soundOff}>
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
            <path d="M4 10v4h4l5 4V6L8 10H4z" />
            {muted ? <path d="M17 9l5 6M22 9l-5 6" /> : <><path d="M16.5 9a4 4 0 0 1 0 6" /><path d="M19 6.5a8 8 0 0 1 0 11" /></>}
          </svg>
        </button>}
      </div>
      <div className="mm-tbadge" aria-hidden="true"><img src={LOGO} alt="" /></div>
    </div>
  );
}

function Testimonials({ items, mobileMode, desktopMode, video }: { items: any[]; mobileMode: string; desktopMode: string; video: string }) {
  const t = useT();
  const { L } = usePrefs();
  const reduced = useReduced();
  const phone = useMatch('(max-width: 760px)');
  const N = items.length;
  const [deck, setDeck] = useState({ ti: 0, from: -1, fwd: true, n: 0 });
  const ti = N ? deck.ti % N : 0;
  // one change at a time: a click or autoplay tick while the deck is still moving is ignored
  const lock = useRef(0);
  const free = () => { const now = Date.now(); if (now < lock.current) return false; lock.current = now + 1150; return true; };
  const go = useCallback((next: number) => {
    if (!N || !free()) return;
    setDeck((d) => {
      const cur = d.ti % N;
      const to = ((next % N) + N) % N;
      if (to === cur) return d;
      return { ti: to, from: cur, fwd: (to - cur + N) % N !== N - 1, n: d.n + 1 };
    });
  }, [N]);

  // phones: cards + video (one under the other), only the cards, or only the video (chosen in the dashboard); no video uploaded = cards
  const mode = !video ? 'cards' : mobileMode === 'video' || mobileMode === 'cards' ? mobileMode : 'both';
  // computers: cards + video, only the cards, or only the video (chosen in the dashboard); 'video only' without a video falls back to the cards
  const deskMode = desktopMode === 'video' && !video ? 'cards' : desktopMode === 'cards' || desktopMode === 'video' ? desktopMode : 'both';

  // autoplay (not while hovered, a video plays, the deck is hidden on phones, or reduced motion)
  const hover = useRef(false);
  const deckHidden = phone ? mode === 'video' : deskMode === 'video';
  useEffect(() => {
    if (reduced || N < 2 || deckHidden) return;
    const id = window.setInterval(() => { if (!hover.current && !document.hidden && free()) setDeck((d) => { const cur = d.ti % N; const to = (cur + 1) % N; return { ti: to, from: cur, fwd: true, n: d.n + 1 }; }); }, 6500);
    return () => clearInterval(id);
  }, [reduced, N, deckHidden, deck.n]);

  // mouse tilt (desktop): CSS variables on the card, no re-render
  const card = useRef<HTMLDivElement>(null);
  const tilt = (e: React.MouseEvent) => {
    const c = card.current;
    if (!c || window.innerWidth < 760 || reduced) return;
    const r = c.getBoundingClientRect();
    const x = (e.clientX - r.left) / r.width, y = (e.clientY - r.top) / r.height;
    c.style.setProperty('--rx', ((0.5 - y) * 12).toFixed(2) + 'deg');
    c.style.setProperty('--ry', ((x - 0.5) * 16).toFixed(2) + 'deg');
    c.style.setProperty('--mx', (x * 100).toFixed(1) + '%');
    c.style.setProperty('--my', (y * 100).toFixed(1) + '%');
  };
  const leave = () => {
    hover.current = false;
    const c = card.current;
    if (c) { c.style.removeProperty('--rx'); c.style.removeProperty('--ry'); }
  };

  // swipe on the cards (touch, or drag with the mouse): left = next, right = previous. Vertical moves still scroll the page.
  const stage = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const el = stage.current;
    if (!el || N < 2) return;
    const by = (d: number) => {
      if (!free()) return;
      setDeck((s) => { const cur = s.ti % N; const to = (cur + d + N) % N; return { ti: to, from: cur, fwd: d > 0, n: s.n + 1 }; });
    };
    let st: { x: number; y: number; done: boolean; h: boolean | null } | null = null;
    const down = (x: number, y: number) => { st = { x, y, done: false, h: null }; };
    const move = (x: number, y: number, ev: Event | null) => {
      if (!st) return;
      const dx = x - st.x, dy = y - st.y;
      if (st.h === null && (Math.abs(dx) > 8 || Math.abs(dy) > 8)) st.h = Math.abs(dx) > Math.abs(dy);
      if (st.h && ev && ev.cancelable) ev.preventDefault();
      if (st.h && !st.done && Math.abs(dx) > 45) { st.done = true; by(dx < 0 ? 1 : -1); }
    };
    const up = () => { st = null; };
    const ts = (e: TouchEvent) => { const p = e.touches[0]; down(p.clientX, p.clientY); };
    const tmv = (e: TouchEvent) => { const p = e.touches[0]; move(p.clientX, p.clientY, e); };
    const pd = (e: PointerEvent) => { if (e.pointerType !== 'touch') down(e.clientX, e.clientY); };
    const pm = (e: PointerEvent) => { if (e.pointerType !== 'touch') move(e.clientX, e.clientY, null); };
    const pu = (e: PointerEvent) => { if (e.pointerType !== 'touch') up(); };
    el.addEventListener('touchstart', ts, { passive: true });
    el.addEventListener('touchmove', tmv, { passive: false });
    el.addEventListener('touchend', up);
    el.addEventListener('touchcancel', up);
    el.addEventListener('pointerdown', pd);
    window.addEventListener('pointermove', pm);
    window.addEventListener('pointerup', pu);
    return () => {
      el.removeEventListener('touchstart', ts);
      el.removeEventListener('touchmove', tmv);
      el.removeEventListener('touchend', up);
      el.removeEventListener('touchcancel', up);
      el.removeEventListener('pointerdown', pd);
      window.removeEventListener('pointermove', pm);
      window.removeEventListener('pointerup', pu);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [N]);

  if (!N) return null;
  const dealCls = deck.n % 2 ? 'B' : 'A';

  return (
    <section id="testimonials" aria-label={t.aSay} className={`mm-testi mm-tmode-${mode} mm-tdesk-${deskMode}`}>
      <div className="mm-wrap mm-p140 mm-testi-in">
        <div className="mm-testi-head">
          <span className="rv rv-left mm-eyebrow">{t.testimonials}</span>
          <h2 className="mm-h2" style={{ fontSize: 96 }}>
            <span className="ln"><span>{t.whatOur}</span></span>
            <span className="ln"><span style={{ transitionDelay: '.12s' }}>{t.clients} <span style={{ color: '#F68B1F' }}>{t.say}</span></span></span>
          </h2>
          {N > 1 && (
            <div className="rv rv-up mm-tnav">
              <button type="button" className="mm-tbtn" onClick={() => go(ti - 1)} aria-label={t.aPrevT}><IconArrow dir="left" /></button>
              <button type="button" className="mm-tbtn mm-hot" onClick={() => go(ti + 1)} aria-label={t.aNextT}><IconArrow dir="right" /></button>
            </div>
          )}
        </div>

        <div className="mm-testi-row">
        <div ref={stage} className="rv rv-right mm-tstage" onMouseEnter={() => { hover.current = true; }} onMouseLeave={leave} onMouseMove={tilt}>
          <div className="mm-tfloat">
            <div ref={card} className="mm-tcard">
              <span className="mm-tq" aria-hidden="true">“</span>
              <div className="mm-tdeck" aria-live="polite">
                {items.map((q, i) => {
                  const off = (i - ti + N) % N;
                  let anim = '';
                  if (deck.n && !reduced) {
                    if (deck.fwd && i === deck.from) anim = 'mm-deal' + dealCls;
                    if (!deck.fwd && i === ti) anim = 'mm-back' + dealCls;
                  }
                  const cls = off > 3 ? (anim ? anim + ' mm-tfade' : 'mm-tcx') : anim;
                  return (
                    <figure key={q.id ?? i} className={`mm-tc mm-off${Math.min(off, 3)} ${cls}`} aria-hidden={off !== 0} style={{ zIndex: Math.max(0, 4 - off) }}>
                      <span className="mm-tshine" aria-hidden="true" />
                      <span className="mm-tcin">
                        <blockquote className="mm-tquote">{L(q.quote)}</blockquote>
                        <figcaption className="mm-tfig">
                          <span className="mm-tav" style={{ background: ['#0B4A94', '#F68B1F', '#0E5E95', '#1B2A40'][i % 4] }}>
                            {q.avatar_url ? <img src={q.avatar_url} alt="" loading="lazy" /> : t.photo}
                          </span>
                          <span className="mm-col" style={{ gap: 2 }}>
                            <span style={{ fontSize: 18, fontWeight: 800 }}>{L(q.name)}</span>
                            <span style={{ fontSize: 14, color: 'var(--muted2)' }}>{L(q.role)}</span>
                          </span>
                        </figcaption>
                      </span>
                    </figure>
                  );
                })}
              </div>
            </div>
          </div>
          {N > 1 && (
            <div className="mm-tbars">
              {items.map((q, i) => (
                <button key={q.id ?? i} type="button" className="mm-tbar" onClick={() => go(i)} aria-label={`${t.testimonials} ${i + 1}`} aria-current={i === ti || undefined}>
                  <span style={{ background: i === ti ? '#F68B1F' : '#2A4366' }} />
                </button>
              ))}
            </div>
          )}
        </div>
        <TReel url={video} />
        </div>
      </div>
    </section>
  );
}

// =====================================================================
// OUR STORY — pinned; scrolling fills the line and shows each stop
// =====================================================================
const STOP_COLORS: [string, string][] = [['#F68B1F', '#0E1B33'], ['#0B4A94', '#ffffff'], ['#1683C7', '#0E1B33'], ['#0E1B33', '#ffffff']];

function Story({ items }: { items: any[] }) {
  const t = useT();
  const { L, isAr } = usePrefs();
  const n = items.length;
  const sec = useRef<HTMLElement>(null);
  const pin = useRef<HTMLDivElement>(null);
  const bar = useRef<HTMLDivElement>(null);
  const inf = useRef<SVGPathElement>(null); // the infinity sign at the end of the line
  const [on, setOn] = useState(n ? 1 : 0);

  useEffect(() => {
    if (!n) return;
    let raf = 0;
    const c0 = 50 / n;
    const phoneMq = window.matchMedia('(max-width: 760px)');
    const calc = () => {
      raf = 0;
      const el = sec.current, p = pin.current;
      if (!el || !p) return;
      const r = el.getBoundingClientRect();
      const span = r.height - p.offsetHeight;
      const prog = span <= 0 ? 1 : Math.min(1, Math.max(0, -r.top / span));
      // the line fills during the first 70% of the scroll; the last 30% draws the infinity sign bit by bit at its end
      // (scrolling back up undraws it)
      const fill = c0 + Math.min(1, prog / 0.7) * (100 - c0);
      if (bar.current) bar.current.style.width = fill.toFixed(2) + '%';
      // phones (no pinning, vertical line): once the sign's spot is on screen it draws itself all the way (CSS
      // transition), so it is never left half drawn; it is wiped again only when it goes back below the screen
      if (inf.current && phoneMq.matches) {
        const top = (inf.current.ownerSVGElement || inf.current).getBoundingClientRect().top, vh = window.innerHeight;
        if (top < vh * 0.85) inf.current.style.strokeDashoffset = '0';
        else if (top > vh) inf.current.style.strokeDashoffset = '1';
      } else if (inf.current) inf.current.style.strokeDashoffset = String(1 - Math.min(1, Math.max(0, (prog - 0.7) / 0.3)));
      let k = 0;
      for (let i = 0; i < n; i++) if (fill >= (i + 0.5) * (100 / n) - 0.01) k = i + 1;
      setOn((prev) => (prev === k ? prev : k));
    };
    const onScroll = () => { if (!raf) raf = requestAnimationFrame(calc); };
    calc();
    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll);
    return () => { window.removeEventListener('scroll', onScroll); window.removeEventListener('resize', onScroll); cancelAnimationFrame(raf); };
  }, [n]);

  if (!n) return null; // nothing typed in the dashboard yet: no section
  return (
    <section ref={sec} id="history" data-bg="bg2" className={'mm-hist' + (n ? '' : ' mm-hist0')} style={{ ['--h' as any]: `${900 + n * 200}px` }}>
      <div ref={pin} className="mm-pin">
        <div className="mm-wrap mm-pin-in">
          <div className="mm-headrow">
            <div className="mm-col" style={{ gap: 14 }}>
              <span className="mm-eyebrow">{t.ourStory}</span>
              <h2 className="mm-h2" style={{ fontSize: 88 }}>{t.storySoFar}</h2>
            </div>
            <span className="mm-fromday">
              <span className="rv rv-up" style={{ transitionDelay: '.1s' }}>{t.from}</span>
              <span className="rv rv-up" style={{ transitionDelay: '.2s' }}>{t.day}</span>
              <span className="rv rv-up" style={{ transitionDelay: '.3s' }}>{t.one}</span>
              <span className="rv rv-pop" style={{ color: '#F68B1F', transitionDelay: '.45s' }}>{t.toToday}</span>
            </span>
          </div>
          {n > 0 && (
            <div className="mm-tl">
              <div className="mm-tlbar" aria-hidden="true"><div ref={bar} /></div>
              {/* the line ends in an infinity sign that is drawn while you scroll (nothing there before) */}
              <svg className="mm-tlinf" viewBox="0 0 110 50" aria-hidden="true">
                <path ref={inf} className="ink" pathLength={1} d="M4 25 C4 6 30 6 55 25 C80 44 106 44 106 25 C106 6 80 6 55 25 C30 44 4 44 4 25 Z" />
              </svg>
              <div className="mm-tlgrid" style={{ ['--n' as any]: n }}>
                {items.map((st, i) => {
                  const lit = i < on;
                  const [bg] = STOP_COLORS[i % 4];
                  return (
                    <div key={st.id ?? i} className="mm-ms" style={{ opacity: lit ? 1 : 0, transform: lit ? 'none' : `translateX(${isAr ? -60 : 60}px) scale(.9)` }}>
                      <span className="mm-msnum" style={{ background: bg, boxShadow: lit && i === on - 1 ? '0 0 0 6px #F68B1F55' : 'none' }} aria-hidden="true" />
                      <span className="mm-msyear">{L(st.year)}</span>
                      <span className="mm-mstitle">{L(st.title)}</span>
                      <span className="mm-mstext">{L(st.text)}</span>
                    </div>
                  );
                })}
              </div>
            </div>
          )}
        </div>
      </div>
    </section>
  );
}

// =====================================================================
// NEWS — the 3 latest
// =====================================================================
function News({ items }: { items: any[] }) {
  const t = useT();
  const { L, lang } = usePrefs();
  const list = items.slice(0, 3);
  if (!list.length) return null;
  return (
    <section id="news" className="mm-news">
      <div className="mm-wrap mm-sec mm-col" style={{ gap: 48 }}>
        <div className="mm-headrow">
          <div className="mm-col" style={{ gap: 16 }}>
            <span className="rv rv-left mm-eyebrow">{t.newsAnn}</span>
            <h2 className="mm-h2" style={{ fontSize: 104 }}><span className="ln"><span>{t.latest}</span></span></h2>
          </div>
          <Link className="rv rv-right mm-more" to="/news">{t.allNews}</Link>
        </div>
        <div className="mm-newsgrid">
          {list.map((nw, i) => {
            const tag = NEWS_TAG[nw.type] || NEWS_TAG.news;
            return (
              <Link key={nw.id ?? i} to={nw.slug ? `/news/${nw.slug}` : '/news'} className="mm-card rv rv-up mm-ncard" style={{ transitionDelay: `${i * 0.12}s` }}>
                <span className="mm-nimg">
                  <span className="mm-img mm-ph" style={{ background: '#0F2C52', color: '#9FB8D9' }}>
                    {nw.cover_url ? <Media url={nw.cover_url} alt="" /> : t.newsImg}
                  </span>
                </span>
                <span className="mm-nmeta">
                  <span className="mm-ntag" style={{ background: tag.bg, color: tag.fg }}>{L(tag.label)}</span>
                  <span style={{ color: 'var(--muted2)' }}>{nw.published_at ? fmtDate(nw.published_at, lang) : t.date}</span>
                </span>
                <span className="mm-ntitle mm-ttl">{L(nw.title)}</span>
              </Link>
            );
          })}
        </div>
      </div>
    </section>
  );
}

