// =====================================================================
export default function Home() {
  const { data, error } = useApi<any>('/site');
  const d = data || PH;
  const s = d.settings || PH.settings;
  const arr = (v: any) => (Array.isArray(v) ? v : []);
  return (
    <SiteShell header={<InnerHeader current="home" />}>
      <Hero cfg={data ? s.hero || {} : error ? {} : null} />
      <Marquee />
      <Intro items={arr(d.intro)} />
      <Services items={arr(d.services)} />
      <Work items={arr(d.workHome)} live={!!data} />
      <Clients items={arr(d.clients)} />
      <Testimonials items={arr(d.testimonials)} mobileMode={s.testimonials_display?.mobile || 'both'} desktopMode={s.testimonials_display?.desktop || 'both'} video={s.testimonials_video?.url || ''} />
      <Story items={arr(d.story)} />
      <News items={arr(d.news)} />
      <Careers open={Number(d.openJobs) || 0} />
    </SiteShell>
  );
}
